namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = "";
    public string DepartmentName { get; set; } = "";
    public string CourseNumber { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", CourseNumber = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She specializes in programming pedagogy and introductory CS curricula.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", CourseNumber = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez is a researcher in algorithm optimization with publications in ACM and IEEE conferences.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", CourseNumber = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases. Covers SQL, normalization, transaction processing, and query optimization.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked as a database architect at Oracle for 10 years before transitioning to academia." },
            new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", CourseNumber = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised learning, unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She specializes in programming pedagogy and introductory CS curricula.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", CourseNumber = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Prof. Alan Wright", InstructorBio = "Prof. Wright has taught calculus for over 20 years and authored two widely-used textbooks on the subject.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", CourseNumber = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Dr. Emily Park", InstructorBio = "Dr. Park specializes in applied linear algebra and numerical methods." },
            new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", CourseNumber = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. Emily Park", InstructorBio = "Dr. Park specializes in applied linear algebra and numerical methods." },
            new() { Id = 8, DepartmentId = 3, DepartmentCode = "PHYS", DepartmentName = "Physics", CourseNumber = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with research interests in condensed matter physics." },
            new() { Id = 9, DepartmentId = 3, DepartmentCode = "PHYS", DepartmentName = "Physics", CourseNumber = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "TTh 1:00–2:15 PM + Lab Fri 1:00–3:00 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with research interests in condensed matter physics.", IsFeatured = true },
            new() { Id = 10, DepartmentId = 4, DepartmentCode = "ENG", DepartmentName = "English", CourseNumber = "ENG 101", Title = "Composition and Rhetoric", Description = "Fundamentals of academic writing, argumentation, and critical reading.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Prof. Diana Hughes", InstructorBio = "Prof. Hughes is a published author and writing coach with expertise in rhetoric and composition theory." },
            new() { Id = 11, DepartmentId = 4, DepartmentCode = "ENG", DepartmentName = "English", CourseNumber = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Dr. Marcus Bell", InstructorBio = "Dr. Bell is a scholar of 20th-century American fiction and has published extensively on the Harlem Renaissance." },
            new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", CourseNumber = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from prehistory to 1500 CE. Examines political, social, and cultural developments.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Katherine Moore", InstructorBio = "Dr. Moore is a historian specializing in ancient Mediterranean civilizations." },
            new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", CourseNumber = "HIST 250", Title = "Modern European History", Description = "Europe from the Enlightenment through the 20th century, including revolutions, world wars, and the formation of the EU.", Credits = 3, Schedule = "TTh 3:30–4:45 PM", InstructorName = "Dr. Katherine Moore", InstructorBio = "Dr. Moore is a historian specializing in ancient Mediterranean civilizations." },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

