        <div class="col-12">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" required placeholder="e.g., STU-12345" />
        </div>

        <div class="col-12">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">— Select a course —</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseNumber — @course.Title</option>
                }
            </select>
        </div>

        <div class="col-12">
            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </div>
    </form>
}

@code {
    [SupplyParameterFromForm] public CourseCatalog.Models.EnrollmentRequest? Model { get; set; }

    protected CourseCatalog.Models.EnrollmentRequest BoundModel => Model ??= new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<CourseCatalog.Models.Course> courses = new();
    private bool submitted;
    private string selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }

        // Check if form was posted
        if (!string.IsNullOrEmpty(Model.StudentName) && !string.IsNullOrEmpty(Model.StudentId) && Model.CourseId > 0)
        {
            var course = CatalogService.GetCourse(Model.CourseId);
            selectedCourseTitle = course != null ? $"{course.CourseNumber} — {course.Title}" : "Unknown Course";
            submitted = true;
        }
    }
}

